from candidate import search
from unittest.mock import patch

class TestSearchFunction(unittest.TestCase):

    @patch('builtins.max', return_value=5)
    def test_search_with_frequent_integer(self, mock_max):
        self.assertEqual(search([4, 1, 2, 2, 3, 1]), 2)

    @patch('builtins.max', return_value=7)
    def test_search_with_no_frequent_integer(self, mock_max):
        self.assertEqual(search([5, 5, 4, 4, 4]), -1)

    @patch('builtins.max', return_value=4)
    def test_search_with_edge_case_low_frequency(self, mock_max):
        self.assertEqual(search([1, 2, 2, 3, 3, 4, 4, 5]), -1)

    def test_search_with_all_unique(self):
        self.assertEqual(search([1, 2, 3, 4]), -1)

    def test_search_with_increasing_frequency(self):
        self.assertEqual(search([1, 2, 2, 3, 3, 3, 4, 4, 4]), 3)

    def test_search_with_decreasing_frequency(self):
        self.assertEqual(search([4, 4, 3, 3, 2, 2, 1, 1]), -1)

    def test_search_with_single_element(self):
        self.assertEqual(search([5]), -1)

    def test_search_with_zero_frequency(self):
        self.assertEqual(search([1, 1, 2, 2, 3, 3]), -1)

    def test_search_with_large_list(self):
        self.assertEqual(search(list(range(1, 100)), -1))

    def test_search_with_none_input(self):
        with self.assertRaises(TypeError):
            search(None)

    def test_search_with_empty_list(self):
        with self.assertRaises(TypeError):
            search([])

    def test_search_with_type_error_input(self):
        with self.assertRaises(TypeError):
            search([1, 'a', 2, 'b', 3])

    def test_search_with_negative_values(self):
        with self.assertRaises(TypeError):
            search([-1, 1, 2, -2, 3])

if __name__ == '__main__':
    unittest.main()
